/* Channel id (campaign-channels.js) to mark. YouTube keeps its icon in every
   format (in-stream, Shorts, live); the Shorts glyph is only for inside the
   Shorts screen. The publieditorial runs on a fictitious blog: no platform mark. */
export const CHANNEL_LOGO={instagram:'instagram',facebook:'facebook',tiktok:'tiktok',youtube:'youtube',linkedin:'linkedin',google:'googleAds',seo:'google',chatgpt:'chatgpt',maps:'googleMaps',whatsapp:'whatsapp',blog:null};
export const logoFor=channelId=>CHANNEL_LOGO[channelId]?LOGOS[CHANNEL_LOGO[channelId]]:null;

/** Sized inline SVG. altura in CSS px (width follows the mark's proportion).
 * rotulo: accessible name, only when the mark is the sole visible name (for
 * example a Facebook tab with no text); otherwise the mark stays hidden from
 * assistive tech next to the written name. escuro: dark-ground variant.
 * mono: 'preto' | 'branco' where the platform publishes a one-colour version.
 * The width comes from the chosen variant's viewBox, so nothing is stretched. */
export function logoSvg(id,{altura=20,rotulo='',escuro=false,mono='',classe=''}={}){
 const logo=LOGOS[id];
 if(!logo) return '';
 const source=(mono&&logo.mono&&logo.mono[mono])||(escuro?logo.svgEscuro:logo.svg);
 const box=source.match(/viewBox="([^"]+)"/)[1].split(' ').map(Number);
 const width=Math.round(altura*box[2]/box[3]*100)/100;
 const a11y=rotulo?'role="img" aria-label="'+esc(rotulo)+'"':'aria-hidden="true" focusable="false"';
 return source.replace('<svg ','<svg class="ch-logo ch-logo--'+id+(classe?' '+esc(classe):'')+'" width="'+width+'" height="'+altura+'" ').replace('aria-hidden="true" focusable="false"',a11y);
}
